/* @autogenerated */
import { NavigationCancel, NavigationEnd, NavigationStart, Router } from '@angular/router';
import { Subject } from 'rxjs';
import { AuthorizationAccessService } from './authorization-access.service';

describe('AuthorizationAccessService', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('stores last non auth route', () => {
    const events$ = new Subject<any>();
    const router = {
      events: events$,
      navigateByUrl: jasmine.createSpy('navigateByUrl'),
      navigate: jasmine.createSpy('navigate'),
    } as unknown as Router;

    new AuthorizationAccessService(router);

    events$.next(new NavigationStart(1, '/start'));
    expect(localStorage.getItem('last-non-oidc-route')).toBeNull();

    events$.next(new NavigationEnd(1, '/home', '/home'));
    expect(localStorage.getItem('last-non-oidc-route')).toBe('/home');

    events$.next(new NavigationEnd(2, '/login-redirect', '/login-redirect'));
    expect(localStorage.getItem('last-non-oidc-route')).toBe('/home');
  });

  it('loads last route or default', () => {
    const events$ = new Subject<any>();
    const router = {
      events: events$,
      navigateByUrl: jasmine.createSpy('navigateByUrl'),
      navigate: jasmine.createSpy('navigate'),
    } as unknown as Router;

    const service = new AuthorizationAccessService(router);

    localStorage.setItem('last-non-oidc-route', '/last');
    service.loadLastRoute();
    expect(router.navigateByUrl).toHaveBeenCalledWith('/last');

    localStorage.removeItem('last-non-oidc-route');
    service.loadLastRoute();
    expect(router.navigate).toHaveBeenCalledWith(['en-EN', 'main']);
  });

  it('clear removes the stored route from localStorage', () => {
    const events$ = new Subject<any>();
    const router = {
      events: events$,
      navigateByUrl: jasmine.createSpy(),
      navigate: jasmine.createSpy(),
    } as unknown as Router;
    const service = new AuthorizationAccessService(router);

    localStorage.setItem('last-non-oidc-route', '/some-route');
    service.clear();

    expect(localStorage.getItem('last-non-oidc-route')).toBeNull();
  });

  it('clear is a no-op when nothing is stored', () => {
    const events$ = new Subject<any>();
    const router = {
      events: events$,
      navigateByUrl: jasmine.createSpy(),
      navigate: jasmine.createSpy(),
    } as unknown as Router;
    const service = new AuthorizationAccessService(router);

    expect(() => service.clear()).not.toThrow();
    expect(localStorage.getItem('last-non-oidc-route')).toBeNull();
  });

  it('falls back to event.url when urlAfterRedirects is not present (NavigationCancel)', () => {
    const events$ = new Subject<any>();
    const router = {
      events: events$,
      navigateByUrl: jasmine.createSpy(),
      navigate: jasmine.createSpy(),
    } as unknown as Router;

    new AuthorizationAccessService(router);

    events$.next(new NavigationCancel(1, '/dashboard', 'guard rejected'));

    expect(localStorage.getItem('last-non-oidc-route')).toBe('/dashboard');
  });
});
